Create a component for editing documentation files. Ensure that the component fetches the document content from Firebase, allows for editing, and saves changes back to Firebase.

Here's an example of how to implement this:

```python
import { useState, useEffect } from 'react';
import { useClient } from 'next/dist/client/components/app-router-context';
import { getDocument, updateDocument } from '@/lib/firebase';
import MarkdownIt from 'markdown-it';
import MarkdownEditor from 'react-markdown-editor-lite';
import 'react-markdown-editor-lite/lib/index.css';

const markdownParser = new MarkdownIt();

function Editor({ documentId }) {
  const [content, setContent] = useState('');
  const [isEditing, setIsEditing] = useState(false);

  useEffect(() => {
    async function fetchDocumentContent() {
      const doc = await getDocument(documentId);
      setContent(doc?.content || '');
    }
    fetchDocumentContent();
  }, [documentId]);

  const handleSave = async () => {
    await updateDocument(documentId, { content });
    setIsEditing(false);
  };

  const handleEdit = () => {
    setIsEditing(true);
  };

  const handleCancel = () => {
    setIsEditing(false);
  };

  return (
    <div className="max-w-4xl mx-auto p-6">
      <div className="prose prose-lg max-w-none mb-4">
        <h1>{documentId}</h1>
      </div>
      {!isEditing && (
        <div dangerouslySetInnerHTML={{ __html: markdownParser.render(content) }} className="prose prose-lg max-w-none mb-4" />
      )}
      {isEditing && (
        <MarkdownEditor
          value={content}
          onChange={(value) => setContent(value.text)}
          style={{ height: '300px' }}
          className="mb-4"
        />
      )}
      <div className="flex justify-end space-x-2">
        <button onClick={handleEdit} className="bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded">Edit</button>
        <button onClick={handleSave} disabled={!isEditing} className="bg-green-500 hover:bg-green-700 text-white font-bold py-2 px-4 rounded">Save</button>
        <button onClick={handleCancel} disabled={!isEditing} className="bg-red-500 hover:bg-red-700 text-white font-bold py-2 px-4 rounded">Cancel</button>
      </div>
    </div>
  );
}

export default function DocumentPage({ documentId }) {
  useClient(); // Ensures that the component works with Next.js app router

  return (
    <main>
      <Editor documentId={documentId} />
    </main>
  );
}
