        for (const auto& [name, stats] : ratings) {
            file << name << ',' << stats.first << ',' << stats.second << ',' << (stats.first + stats.second) << '\n';
        }
    }

    void loadFromFile(const std::string& filename) {
        std::ifstream file(filename);
        std::string line;
        while (std::getline(file, line)) {
            size_t pos1 = line.find(',');
            size_t pos2 = line.find(',', pos1 + 1);
            size_t pos3 = line.find(',', pos2 + 1);
            std::string name = line.substr(0, pos1);
            int wins = std::stoi(line.substr(pos1 + 1, pos2 - pos1 - 1));
            int losses = std::stoi(line.substr(pos2 + 1, pos3 - pos2 - 1));
            ratings[name] = {wins, losses};
        }
    }

    void displayRatings(sf::RenderWindow& window) const {
        sf::Font font;
        font.loadFromFile("arial.ttf");

        sf::Text text;
        text.setFont(font);
        text.setCharacterSize(24);
        text.setFillColor(sf::Color::White);

        int yPosition = 50;
        for (const auto& [name, stats] : ratings) {
            std::string textContent = name + ": Wins: " + std::to_string(stats.first) + ", Losses: " + std::to_string(stats.second) + ", Total Games: " + std::to_string(stats.first + stats.second);
            text.setString(textContent);
            text.setPosition(50, yPosition);
            window.draw(text);
            yPosition += 30;
        }
    }
};

// Main Application
int main() {
    sf::RenderWindow window(sf::VideoMode(800, 600), "Chess Game");

    ChessModel game;
    PlayerRating ratingSystem;
    ChessView view(window);
    ChessController controller(game, view, ratingSystem);

    ratingSystem.loadFromFile("ratings.txt");

    sf::Sprite startButtonSprite; // Assume sprite is initialized elsewhere
    sf::Sprite ratingButtonSprite; // Assume sprite is initialized elsewhere

    while (window.isOpen()) {
        sf::Event event;
        while (window.pollEvent(event)) {
            if (event.type == sf::Event::Closed)
                window.close();

            if (event.type == sf::Event::MouseButtonPressed) {
                if (event.mouseButton.button == sf::Mouse::Left) {
                    if (startButtonSprite.getGlobalBounds().contains(event.mouseButton.x, event.mouseButton.y)) {
                        controller.startGame();
                    } else if (ratingButtonSprite.getGlobalBounds().contains(event.mouseButton.x, event.mouseButton.y)) {
                        controller.showRatings();
                    }
                }
            }
        }

        window.clear();

        view.drawBoard();
        view.drawSettingsPanel();
        controller.showRatings(); // Always display ratings for demonstration purposes

        window.display();
    }

    ratingSystem.saveToFile("ratings.txt");

    return 0;
}
