    t = 0:dt:10; % Simulation time
    v_car = 20; % Car speed in m/s
    v_wheel = v_car; % Initial wheel speed equals car speed

    braking_torques = zeros(size(t));
    slip_ratios = zeros(size(t));
    abs_cycles = false(size(t));

