// Initialize Three.js scene, camera, and renderer
const scene = new THREE.Scene();
const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
const renderer = new THREE.WebGLRenderer();
renderer.setSize(window.innerWidth, window.innerHeight);
document.body.appendChild(renderer.domElement);

// Create the sun and planets
const sunGeometry = new THREE.SphereGeometry(50, 32, 32);
const sunMaterial = new THREE.MeshBasicMaterial({color: 0xffff00});
const sun = new THREE.Mesh(sunGeometry, sunMaterial);
scene.add(sun);

function createPlanet(radius, distanceFromSun, color) {
    const geometry = new THREE.SphereGeometry(radius, 32, 32);
    const material = new THREE.MeshBasicMaterial({color: color});
    const planet = new THREE.Mesh(geometry, material);
    scene.add(planet);
    return planet;
}

const earth = createPlanet(10, 200, 0x0000ff);
const mars = createPlanet(8, 300, 0xffa500);

camera.position.z = 500;

function animate() {
    requestAnimationFrame(animate);

    // Update planet positions based on time
    const angle = Date.now() / 1000;
    earth.position.x = 200 * Math.cos(angle);
    earth.position.y = 200 * Math.sin(angle);
    mars.position.x = 300 * Math.cos(angle * 0.5); // Mars has a longer orbital period
    mars.position.y = 300 * Math.sin(angle * 0.5);

    renderer.render(scene, camera);
}

animate();
```

